"content": "{
  "named_method": "Generalized Least Squares (GLS) Distance Network",
  "structural_ingredients": {
    "linear_model": {
      "implemented": true,
      "form": "y = A · θ + ε,  ε ~ N(0, C)",
      "notes": "Each observation block written as a linear equation in {μ_host, μ_group, M_B, M_SBF, a_H = 5 log10 H0}."
    },
    "geometric_anchor_uncertainty_via_covariance": {
      "implemented": true,
      "notes": "σ_anchor^2 added as a block-correlated term shared by all primary-host rows that use the same anchor."
    },
    "method_anchor_systematic_via_covariance": {
      "implemented": true,
      "notes": "σ²_(method,anchor) shared across rows with the same (method, anchor) pair (Cepheid/N4258, Cepheid/LMC, Cepheid/MW, TRGB/N4258)."
    },
    "peculiar_velocity_to_magnitude_propagation": {
      "implemented": true,
      "form": "σ_pec_mag = (5/ln10) · σ_v / (c·z)"
    },
    "intra_group_depth_scatter_for_SBF": {
      "implemented": true,
      "form": "added in quadrature to SBF calibrator rows (depth_scatter = 0.10 mag)"
    },
    "GLS_solution_with_full_covariance": {
      "implemented": true,
      "form": "θ_hat = (AᵀC⁻¹A)⁻¹ AᵀC⁻¹ y;   Cov(θ) = (AᵀC⁻¹A)⁻¹"
    },
    "H0_propagation_from_a_H": {
      "implemented": true,
      "form": "H0 = 10^(a_H/5);  σ_H0 = H0 · (ln10/5) · σ_a_H"
    }
  },
  "deviations_from_the_full_paper_protocol": [
    "MW parallax-based Cepheid term reduces to a (Cepheid, MW) systematic since the dataset provides no individual MW Cepheids; this is the simplest faithful reduction given the minimal dataset.",
    "Miras and JAGB primary indicators are absent from the minimal dataset; not implemented.",
    "Secondary indicators SNe II, FP, TF are absent from the minimal dataset; not implemented.",
    "SBF group depth scatter is added as an uncorrelated diagonal term per row rather than as a per-group block-correlated term, since the minimal dataset has at most two galaxies per group and the choice has negligible numerical effect.",
    "SBF-only secondary configuration is mathematically degenerate with this minimal dataset (no anchor link to SBF group hosts). It is reported as singular rather than substituted with a different method."
  ]
}
